from solution import fib

import pytest
from hypothesis import given
import hypothesis.strategies as st


def _ref(n: int) -> int:
    # Obviously-correct iterative reference for standard Fibonacci:
    # F(0)=0, F(1)=1, F(n)=F(n-1)+F(n-2).
    # Pinned by spec examples: F(1)=1, F(8)=21, F(10)=55.
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


# --- explicit examples from spec docstring ---

def test_example_fib_10_is_55():
    assert fib(10) == 55


def test_example_fib_1_is_1():
    assert fib(1) == 1


def test_example_fib_8_is_21():
    assert fib(8) == 21


# --- boundaries implied by "n-th Fibonacci number" ---

def test_fib_zero_is_zero():
    assert fib(0) == 0


def test_fib_two_is_one():
    assert fib(2) == 1


def test_fib_returns_int():
    for n in [0, 1, 2, 8, 10]:
        assert isinstance(fib(n), int)


# --- property-based tests against reference / invariants ---

@given(st.integers(min_value=0, max_value=30))
def test_reference_model_equivalence(n):
    assert fib(n) == _ref(n)


@given(st.integers(min_value=2, max_value=30))
def test_recurrence_relation(n):
    assert fib(n) == fib(n - 1) + fib(n - 2)


@given(st.integers(min_value=0, max_value=25))
def test_nonnegative_for_nonnegative_n(n):
    assert fib(n) >= 0


@given(st.integers(min_value=1, max_value=25))
def test_cassini_identity(n):
    # Cassini: F(n-1)*F(n+1) - F(n)^2 == (-1)^n
    assert fib(n - 1) * fib(n + 1) - fib(n) ** 2 == (-1) ** n


@given(st.integers(min_value=0, max_value=20))
def test_sum_identity(n):
    # sum_{i=0..n} F(i) == F(n+2) - 1
    assert sum(fib(i) for i in range(n + 1)) == fib(n + 2) - 1


@given(st.integers(min_value=0, max_value=25))
def test_monotonic_non_decreasing(n):
    assert fib(n + 1) >= fib(n)


@given(st.integers(min_value=0, max_value=25))
def test_doubling_growth(n):
    # F(n) < 2^n for n >= 0, and exact small values spot-checked
    # via reference; guards against exponential blow-up bugs.
    assert fib(n) < 2 ** n if n >= 3 else fib(n) == _ref(n)
